/// Product identity, in one place.
class Brand {
  Brand._();

  static const String appName = 'Stock Yard';

  /// App icon artwork at full size (1024px) — sign-in and splash.
  static const String logoAsset = 'assets/brand/logo.png';

  /// Same mark at 256px — small placements like the app bar.
  static const String logoMarkAsset = 'assets/brand/logo_mark.png';

  /// Line printed at the bottom of every invoice. [year] defaults to the
  /// year the invoice is generated in.
  static String invoiceAttribution([int? year]) =>
      'This invoice is electronically generated by the $appName app. '
      '© ${year ?? DateTime.now().year} $appName. All rights reserved.';
}
